{"command":"cd /tmp/recover && python3 - <<'EOF'
import sqlite3, glob, os
for f in sorted(glob.glob('*.db')):
    print('='*70)
    print(f, os.path.getsize(f))
    try:
        con = sqlite3.connect(f)
        cur = con.cursor()
        print('schema:', cur.execute("select sql from sqlite_master").fetchall())
        rows = cur.execute("select * from cities").fetchall() if cur.execute("select name from sqlite_master where type='table' and name='cities'").fetchone() else None
        if rows is not None:
            print('count:', len(rows))
            print('first 3:', rows[:3])
            print('last 2:', rows[-2:])
            for k in ('Daka','Zunequ','Sator'):
                print(k, [r for r in rows if r[0]==k])
        con.close()
    except Exception as e:
        print('ERROR:', type(e).__name__, e)
EOF","description":"Inspect extracted SQLite databases"}

